<template>
  <main class="backup-app">
    <section class="masthead">
      <div class="masthead-copy">
        <span class="eyebrow"><span class="pulse"></span> Velero control plane</span>
        <h1>集群备份<br><em>与恢复</em></h1>
        <p>将 Kubernetes 资源留在可恢复的时间线上。</p>
      </div>
      <div class="masthead-actions">
        <a-input v-model="veleroNamespace" class="namespace-input" size="small" prefix="命名空间" @press-enter="load" />
        <a-button :loading="loading" @click="load"><template #icon><icon-refresh /></template>刷新状态</a-button>
      </div>
    </section>

    <a-alert v-if="error" type="error" closable class="notice" @close="error = ''">{{ error }}</a-alert>
    <section v-if="!ready && !loading" class="prerequisite">
      <icon-cloud-download class="prerequisite-icon" />
      <div><h2>尚未发现 Velero</h2><p>请先在集群中安装 Velero、S3 插件，并为当前 k8s-proxy 身份授予读取 Namespace、管理 Velero CRD 与 {{ veleroNamespace }} Secret 的权限。</p></div>
      <a-button type="primary" @click="load">重新检测</a-button>
    </section>

    <template v-else-if="ready">
      <section class="signal-strip">
        <div><span>可用备份</span><b>{{ backups.length }}</b></div><div><span>完成恢复</span><b>{{ completedRestores }}</b></div><div><span>定时任务</span><b>{{ schedules.length }}</b></div><div><span>默认位置</span><b class="location-name">{{ defaultLocation || '未设置' }}</b></div>
      </section>

      <a-tabs v-model:active-key="tab" class="workspace-tabs">
        <a-tab-pane key="backups" title="备份库">
          <section class="toolbar"><div><h2>备份库</h2><p>资源清单备份，不包含卷数据或快照。</p></div><a-space><a-input-search v-model="backupSearch" allow-clear placeholder="筛选备份" /><a-button type="primary" @click="openBackup"><template #icon><icon-plus /></template>创建备份</a-button></a-space></section>
          <a-table :data="visibleBackups" :pagination="{ pageSize: 8 }" row-key="metadata.name" :loading="loading">
            <template #columns><a-table-column title="备份名称" data-index="metadata.name"><template #cell="{ record }"><strong>{{ record.metadata.name }}</strong><small>{{ formatDate(record.metadata.creationTimestamp) }}</small></template></a-table-column><a-table-column title="范围"><template #cell="{ record }">{{ scope(record.spec?.includedNamespaces) }}</template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="statusColor(record.status?.phase)">{{ record.status?.phase || '等待中' }}</a-tag></template></a-table-column><a-table-column title="保留至"><template #cell="{ record }">{{ formatDate(record.status?.expiration) }}</template></a-table-column><a-table-column title="操作" :width="190"><template #cell="{ record }"><a-space><a-button size="mini" @click="openRestore(record)">恢复</a-button><a-popconfirm content="将删除备份记录和远程备份数据，是否继续？" type="warning" @ok="destroy('backups', record.metadata.name)"><a-button size="mini" status="danger">删除</a-button></a-popconfirm></a-space></template></a-table-column></template>
          </a-table>
        </a-tab-pane>
        <a-tab-pane key="restores" title="恢复记录">
          <section class="toolbar"><div><h2>恢复记录</h2><p>默认不覆盖现有资源，也不恢复集群范围资源。</p></div></section>
          <a-table :data="restores" :pagination="{ pageSize: 8 }" row-key="metadata.name"><template #columns><a-table-column title="恢复名称" data-index="metadata.name" /><a-table-column title="来源备份" data-index="spec.backupName" /><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="statusColor(record.status?.phase)">{{ record.status?.phase || '等待中' }}</a-tag></template></a-table-column><a-table-column title="创建时间"><template #cell="{ record }">{{ formatDate(record.metadata.creationTimestamp) }}</template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-popconfirm content="删除恢复记录不会回滚已恢复的资源。" @ok="destroy('restores', record.metadata.name)"><a-button size="mini" status="danger">删除记录</a-button></a-popconfirm></template></a-table-column></template></a-table>
        </a-tab-pane>
        <a-tab-pane key="schedules" title="定时任务">
          <section class="toolbar"><div><h2>定时备份</h2><p>以 Cron 表达式维护备份节奏。</p></div><a-button type="primary" @click="openSchedule()"><template #icon><icon-plus /></template>新建计划</a-button></section>
          <a-table :data="schedules" :pagination="false" row-key="metadata.name"><template #columns><a-table-column title="计划名称" data-index="metadata.name" /><a-table-column title="Cron" data-index="spec.schedule" /><a-table-column title="范围"><template #cell="{ record }">{{ scope(record.spec?.template?.includedNamespaces) }}</template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="record.spec?.paused ? 'orange' : 'green'">{{ record.spec?.paused ? '已暂停' : '已启用' }}</a-tag></template></a-table-column><a-table-column title="操作" :width="250"><template #cell="{ record }"><a-space><a-button size="mini" @click="openSchedule(record)">编辑</a-button><a-button size="mini" @click="toggleSchedule(record)">{{ record.spec?.paused ? '恢复' : '暂停' }}</a-button><a-popconfirm content="删除后不再自动创建备份。" @ok="destroy('schedules', record.metadata.name)"><a-button size="mini" status="danger">删除</a-button></a-popconfirm></a-space></template></a-table-column></template></a-table>
        </a-tab-pane>
        <a-tab-pane key="locations" title="存储位置">
          <section class="toolbar"><div><h2>对象存储</h2><p>S3 兼容存储。凭据仅在提交时写入 Kubernetes Secret。</p></div><a-button type="primary" @click="openLocation()"><template #icon><icon-plus /></template>添加位置</a-button></section>
          <a-table :data="locations" :pagination="false" row-key="metadata.name"><template #columns><a-table-column title="位置" data-index="metadata.name"><template #cell="{ record }"><strong>{{ record.metadata.name }}</strong><a-tag v-if="record.spec?.default" color="green" size="small">默认</a-tag></template></a-table-column><a-table-column title="Bucket"><template #cell="{ record }">{{ record.spec?.objectStorage?.bucket }}</template></a-table-column><a-table-column title="Endpoint"><template #cell="{ record }">{{ record.spec?.config?.s3Url }}</template></a-table-column><a-table-column title="状态"><template #cell="{ record }"><a-tag :color="statusColor(record.status?.phase)">{{ record.status?.phase || '未知' }}</a-tag></template></a-table-column><a-table-column title="操作"><template #cell="{ record }"><a-space><a-button size="mini" @click="openLocation(record)">编辑</a-button><a-popconfirm content="只删除存储位置，保留凭据 Secret。" @ok="destroy('backupstoragelocations', record.metadata.name)"><a-button size="mini" status="danger">删除</a-button></a-popconfirm></a-space></template></a-table-column></template></a-table>
        </a-tab-pane>
      </a-tabs>
    </template>

    <a-modal v-model:visible="dialogs.backup" title="创建备份" :confirm-loading="saving" ok-text="创建备份" @ok="saveBackup"><a-form :model="backupForm" layout="vertical"><a-form-item label="备份名称" required><a-input v-model="backupForm.name" placeholder="例如 nightly-default" /></a-form-item><a-form-item label="命名空间范围"><div class="scope-field"><a-radio-group v-model="backupForm.namespaceMode" type="button" class="scope-mode"><a-radio value="include">仅备份选择项</a-radio><a-radio value="exclude">忽略选择项</a-radio></a-radio-group><a-select v-model="backupForm.namespaces" :options="namespaceOptions" multiple allow-search allow-clear :placeholder="backupForm.namespaceMode === 'include' ? '留空表示全部命名空间' : '选择要忽略的命名空间'" /></div></a-form-item><a-form-item label="资源范围"><div class="scope-field"><a-radio-group v-model="backupForm.resourceMode" type="button" class="scope-mode"><a-radio value="include">仅备份选择项</a-radio><a-radio value="exclude">忽略选择项</a-radio></a-radio-group><a-select v-model="backupForm.resources" :options="resourceOptions" :loading="resourceLoading" multiple allow-search allow-clear :placeholder="backupForm.resourceMode === 'include' ? '留空表示全部资源' : '选择要忽略的资源'" /></div></a-form-item><a-form-item label="存储位置" required><a-select v-model="backupForm.storageLocation" :options="locationOptions" placeholder="选择位置" /></a-form-item><a-form-item label="保留天数"><a-input-number v-model="backupForm.days" :min="1" :max="365" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="dialogs.restore" title="从备份恢复" :confirm-loading="saving" ok-text="开始恢复" @ok="saveRestore"><a-alert type="warning" class="modal-alert">默认保留现有同名资源，且不会恢复集群范围资源。</a-alert><a-form :model="restoreForm" layout="vertical"><a-form-item label="恢复名称" required><a-input v-model="restoreForm.name" /></a-form-item><a-form-item label="来源备份"><a-input v-model="restoreForm.backupName" disabled /></a-form-item><scope-picker v-model="restoreForm.namespaces" :items="namespaceNames" /><a-form-item label="命名空间映射"><a-input v-model="restoreForm.mappingText" placeholder="例如 default=restored（每行一组，可选）" type="textarea" :auto-size="{ minRows: 2, maxRows: 5 }" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="dialogs.schedule" :title="scheduleForm.original ? '编辑定时备份' : '新建定时备份'" :confirm-loading="saving" ok-text="保存计划" @ok="saveSchedule"><a-form :model="scheduleForm" layout="vertical"><a-form-item label="计划名称" required><a-input v-model="scheduleForm.name" :disabled="Boolean(scheduleForm.original)" /></a-form-item><a-form-item label="Cron 表达式" required><a-input v-model="scheduleForm.cron" placeholder="0 2 * * *" /></a-form-item><a-form-item label="命名空间范围"><div class="scope-field"><a-radio-group v-model="scheduleForm.namespaceMode" type="button" class="scope-mode"><a-radio value="include">仅备份选择项</a-radio><a-radio value="exclude">忽略选择项</a-radio></a-radio-group><a-select v-model="scheduleForm.namespaces" :options="namespaceOptions" multiple allow-search allow-clear :placeholder="scheduleForm.namespaceMode === 'include' ? '留空表示全部命名空间' : '选择要忽略的命名空间'" /></div></a-form-item><a-form-item label="资源范围"><div class="scope-field"><a-radio-group v-model="scheduleForm.resourceMode" type="button" class="scope-mode"><a-radio value="include">仅备份选择项</a-radio><a-radio value="exclude">忽略选择项</a-radio></a-radio-group><a-select v-model="scheduleForm.resources" :options="resourceOptions" :loading="resourceLoading" multiple allow-search allow-clear :placeholder="scheduleForm.resourceMode === 'include' ? '留空表示全部资源' : '选择要忽略的资源'" /></div></a-form-item><a-form-item label="存储位置" required><a-select v-model="scheduleForm.storageLocation" :options="locationOptions" /></a-form-item><a-form-item label="保留天数"><a-input-number v-model="scheduleForm.days" :min="1" :max="365" /></a-form-item></a-form></a-modal>
    <a-modal v-model:visible="dialogs.location" :title="locationForm.original ? '编辑存储位置' : '添加存储位置'" :confirm-loading="saving" ok-text="保存位置" @ok="saveLocation"><a-alert type="info" class="modal-alert">编辑时留空 Access Key 和 Secret Key 即保留原凭据；不会读取或显示 Secret 内容。</a-alert><a-form :model="locationForm" layout="vertical"><a-form-item label="位置名称" required><a-input v-model="locationForm.name" :disabled="Boolean(locationForm.original)" /></a-form-item><a-form-item label="Bucket" required><a-input v-model="locationForm.bucket" /></a-form-item><a-form-item label="Region" required><a-input v-model="locationForm.region" placeholder="ap-guangzhou" /></a-form-item><a-form-item label="S3 Endpoint" required><a-input v-model="locationForm.endpoint" placeholder="https://cos.ap-guangzhou.myqcloud.com" /></a-form-item><a-space><a-checkbox v-model="locationForm.forcePathStyle">使用 Path Style</a-checkbox><a-checkbox v-model="locationForm.makeDefault">设为默认位置</a-checkbox></a-space><a-form-item label="Access Key"><a-input v-model="locationForm.accessKey" autocomplete="off" /></a-form-item><a-form-item label="Secret Key"><a-input-password v-model="locationForm.secretKey" autocomplete="new-password" /></a-form-item></a-form></a-modal>
  </main>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, ref, resolveComponent } from 'vue'
import { backupResource, create, createSecret, credentialsSecret, discoverResources, list, locationResource, namespaces, patchSecret, remove, restoreResource, scheduleResource, update } from './velero'

const ScopePicker = defineComponent({ props: { modelValue: Array, items: Array }, emits: ['update:modelValue'], setup(props, { emit }) { const FormItem = resolveComponent('a-form-item'), Select = resolveComponent('a-select'); return () => h(FormItem, { label: '备份范围' }, { default: () => h(Select, { modelValue: props.modelValue, 'onUpdate:modelValue': value => emit('update:modelValue', value), options: (props.items || []).map(value => ({ label: value, value })), multiple: true, allowClear: true, placeholder: '留空表示全部命名空间' }) }) } })
const veleroNamespace = ref('velero'), tab = ref('backups'), loading = ref(false), saving = ref(false), ready = ref(false), error = ref(''), backupSearch = ref('')
const backups = ref([]), restores = ref([]), schedules = ref([]), locations = ref([]), namespaceNames = ref([]), resourceOptions = ref([]), resourceLoading = ref(false)
const dialogs = ref({ backup: false, restore: false, schedule: false, location: false })
const backupForm = ref({}), restoreForm = ref({}), scheduleForm = ref({}), locationForm = ref({})
const locationOptions = computed(() => locations.value.map(item => ({ label: item.metadata.name, value: item.metadata.name })))
const namespaceOptions = computed(() => namespaceNames.value.map(value => ({ label: value, value })))
const defaultLocation = computed(() => locations.value.find(item => item.spec?.default)?.metadata.name || locations.value[0]?.metadata.name || '')
const completedRestores = computed(() => restores.value.filter(item => item.status?.phase === 'Completed').length)
const visibleBackups = computed(() => backups.value.filter(item => item.metadata.name.includes(backupSearch.value.trim())))
const formName = prefix => `${prefix}-${new Date().toISOString().slice(0, 10).replaceAll('-', '')}`
const scope = value => !value?.length || value.includes('*') ? '全部命名空间' : value.join('、')
const formatDate = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—'
const statusColor = value => ({ Completed: 'green', PartiallyFailed: 'orange', Failed: 'red', FailedValidation: 'red', InProgress: 'arcoblue', New: 'gray' }[value] || 'gray')
const resourceVersion = (resource, body) => ({ ...body, metadata: { ...body.metadata, namespace: veleroNamespace.value, ...(resource?.metadata?.resourceVersion ? { resourceVersion: resource.metadata.resourceVersion } : {}) } })
function resetDialogs() { dialogs.value = { backup: false, restore: false, schedule: false, location: false } }
async function load() { loading.value = true; error.value = ''; try { const [b, r, s, l, n] = await Promise.all([list(veleroNamespace.value, 'backups'), list(veleroNamespace.value, 'restores'), list(veleroNamespace.value, 'schedules'), list(veleroNamespace.value, 'backupstoragelocations'), namespaces()]); backups.value = b.items || []; restores.value = r.items || []; schedules.value = s.items || []; locations.value = l.items || []; namespaceNames.value = (n.items || []).map(item => item.metadata.name).sort(); ready.value = true } catch (cause) { ready.value = false; error.value = cause.message || '无法读取 Velero 资源' } finally { loading.value = false } }
async function loadResourceOptions() { if (resourceOptions.value.length || resourceLoading.value) return; resourceLoading.value = true; try { resourceOptions.value = await discoverResources() } catch (cause) { error.value = `无法发现 Kubernetes 资源：${cause.message}` } finally { resourceLoading.value = false } }
function openBackup() { backupForm.value = { name: formName('backup'), namespaceMode: 'include', namespaces: [], resourceMode: 'include', resources: [], storageLocation: defaultLocation.value, days: 30 }; dialogs.value.backup = true; loadResourceOptions() }
function openRestore(backup) { restoreForm.value = { name: formName('restore'), backupName: backup.metadata.name, namespaces: backup.spec?.includedNamespaces?.filter(item => item !== '*') || [], mappingText: '' }; dialogs.value.restore = true }
function openSchedule(record) { const template = record?.spec.template || {}; scheduleForm.value = { original: record, name: record?.metadata.name || formName('daily'), cron: record?.spec.schedule || '0 2 * * *', namespaceMode: template.excludedNamespaces?.length ? 'exclude' : 'include', namespaces: (template.excludedNamespaces || template.includedNamespaces || []).filter(item => item !== '*'), resourceMode: template.excludedResources?.length ? 'exclude' : 'include', resources: template.excludedResources || template.includedResources || [], storageLocation: template.storageLocation || defaultLocation.value, days: Math.round((template.ttl ? Number(String(template.ttl).match(/\d+/)?.[0]) : 720) / 24) }; dialogs.value.schedule = true; loadResourceOptions() }
function openLocation(record) { locationForm.value = { original: record, name: record?.metadata.name || '', bucket: record?.spec.objectStorage?.bucket || '', region: record?.spec.config?.region || '', endpoint: record?.spec.config?.s3Url || '', forcePathStyle: record?.spec.config?.s3ForcePathStyle === 'true', makeDefault: Boolean(record?.spec.default), accessKey: '', secretKey: '' }; dialogs.value.location = true }
async function saveBackup() { await savingAction(async () => { await create(veleroNamespace.value, 'backups', resourceVersion(null, backupResource({ ...backupForm.value, storageLocation: backupForm.value.storageLocation, ttlHours: backupForm.value.days * 24 }))); resetDialogs(); await load() }) }
function mappings(value) { return Object.fromEntries(String(value || '').split('\n').map(line => line.split('=').map(part => part.trim())).filter(parts => parts.length === 2 && parts[0] && parts[1])) }
async function saveRestore() { await savingAction(async () => { await create(veleroNamespace.value, 'restores', resourceVersion(null, restoreResource({ ...restoreForm.value, mapping: mappings(restoreForm.value.mappingText) }))); resetDialogs(); tab.value = 'restores'; await load() }) }
async function saveSchedule() { await savingAction(async () => { const body = resourceVersion(scheduleForm.value.original, scheduleResource({ ...scheduleForm.value, ttlHours: scheduleForm.value.days * 24, paused: scheduleForm.value.original?.spec?.paused })); if (scheduleForm.value.original) await update(veleroNamespace.value, 'schedules', scheduleForm.value.name, body); else await create(veleroNamespace.value, 'schedules', body); resetDialogs(); await load() }) }
async function toggleSchedule(record) { await savingAction(async () => { const body = resourceVersion(record, { ...record, spec: { ...record.spec, paused: !record.spec?.paused } }); await update(veleroNamespace.value, 'schedules', record.metadata.name, body); await load() }) }
async function saveLocation() { await savingAction(async () => { const current = locationForm.value.original; const credentialName = current?.spec?.credential?.name || `${locationForm.value.name}-credentials`; const hasCredentials = locationForm.value.accessKey || locationForm.value.secretKey; if (hasCredentials && (!locationForm.value.accessKey || !locationForm.value.secretKey)) throw new Error('更新凭据时必须同时填写 Access Key 与 Secret Key'); if (!current && !hasCredentials) throw new Error('新建存储位置必须填写 Access Key 与 Secret Key'); if (hasCredentials) { const secret = credentialsSecret(credentialName, locationForm.value.accessKey, locationForm.value.secretKey); if (current) await patchSecret(veleroNamespace.value, credentialName, { stringData: secret.stringData }); else await createSecret(veleroNamespace.value, { ...secret, metadata: { ...secret.metadata, namespace: veleroNamespace.value } }) } const body = resourceVersion(current, locationResource({ ...locationForm.value, credentialName })); if (current) await update(veleroNamespace.value, 'backupstoragelocations', locationForm.value.name, body); else await create(veleroNamespace.value, 'backupstoragelocations', body); resetDialogs(); await load() }) }
async function destroy(resource, name) { await savingAction(async () => { await remove(veleroNamespace.value, resource, name); await load() }) }
async function savingAction(action) { saving.value = true; error.value = ''; try { await action() } catch (cause) { error.value = cause.message || '操作失败' } finally { saving.value = false } }
onMounted(load)
</script>
